111	    /**
112	     * Remembers, per already-seen {@code Idempotency-Key}, the id of the owner that key
113	     * originally created, so a retried create with the same key returns that owner instead
114	     * of creating a duplicate. Held in memory for the application's lifetime and keyed by the
115	     * raw header value.
116	     */
117	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
122	        boolean hasKey = idempotencyKey != null && !idempotencyKey.isBlank();
123	        if (hasKey) {
124	            Integer existingId = idempotentCreates.get(idempotencyKey);
125	            if (existingId != null) {
126	                Owner existing = this.clinicService.findOwnerById(existingId);
127	                if (existing != null) {
128	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
129	                }
130	            }
131	        }
132	        ResponseEntity<OwnerDto> response = createNewOwner(ownerFieldsDto);
133	        if (hasKey && response.getStatusCode() == HttpStatus.CREATED
134	            && response.getBody() != null && response.getBody().getId() != null) {
135	            idempotentCreates.putIfAbsent(idempotencyKey, response.getBody().getId());
136	        }
137	        return response;
138	    }
