236	    /**
237	     * Create and persist a brand-new owner from the supplied fields, returning the
238	     * {@code 201 Created} response for it. This gathers the whole create pipeline in one
239	     * place — map the fields, {@link #normalizeNewOwner normalise} them, apply the daily
240	     * and city gates (each with its own rejection status), resolve any household,
241	     * {@link #assignDerivedAttributes derive the create-time attributes} (including the
242	     * household level ceiling that caps the owner's membership level), save, audit and
243	     * build the response with its {@code Location} header — so {@link #addOwner} itself
244	     * stays a thin entry point. An owner joining an existing household is admitted (its
245	     * membership level is capped to one above the household maximum rather than rejected):
246	     * two owners sharing a last name and postcode but with different telephones are no
247	     * longer a hard duplicate but a soft match. Duplicate detection is the single
248	     * {@link Owner#getIdentityKey() identity key}: a create whose identity key matches an
249	     * existing, non-deleted owner is rejected with {@code 409 Conflict}.
250	     *
251	     * @param ownerFieldsDto the owner fields from the request body
252	     * @return {@code 201 Created} with the created owner and its {@code Location} header,
253	     *         or the appropriate rejection status: {@code 400 Bad Request} when the fields
254	     *         are invalid, {@code 429 Too Many Requests} when the day's create cap is
255	     *         reached, or {@code 409 Conflict} when the city is at capacity or the owner's
256	     *         identity key duplicates an existing owner
257	     */
258	    private ResponseEntity<OwnerDto> createNewOwner(OwnerFieldsDto ownerFieldsDto) {
259	        HttpHeaders headers = new HttpHeaders();
260	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
261	        if (!normalizeNewOwner(owner)) {
262	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
263	        }
264	        if (dailyLimitReached(owner.getRegistrationDate())) {
265	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
266	        }
267	        if (cityIsAtCapacity(owner.getCity())) {
268	            return new ResponseEntity<>(HttpStatus.CONFLICT);
269	        }
270	        owner.setHouseholdId(owner.computeHouseholdId());
271	        if (isDuplicateIdentity(owner)) {
272	            return new ResponseEntity<>(HttpStatus.CONFLICT);
273	        }
274	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
275	        List<Owner> householdMembers = findHouseholdMembers(owner);
276	        boolean joinsExistingHousehold = !householdMembers.isEmpty();
277	        boolean declaredHouseholdMember = joinsExistingHousehold && sharesHousehold;
278	        assignDerivedAttributes(owner, declaredHouseholdMember, householdMembers);
279	        this.clinicService.saveOwner(owner);
280	        auditOwnerCreated(owner);
281	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
282	        headers.setLocation(UriComponentsBuilder.newInstance()
283	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
284	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
285	    }
286	
287	    /**
288	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
289	     * the canonical form each stored value must take: the address is trimmed,
290	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
291	     * telephone is converted to E.164, any email is lower-cased and a missing
292	     * registration date defaults to today. Field-level rejections are reported here
293	     * rather than inline in {@link #addOwner}, and normalisation runs before any
294	     * household comparison so those comparisons see the canonical values.
295	     *
296	     * @param owner the freshly-mapped owner to normalise
297	     * @return {@code true} if the fields are valid, or {@code false} if the address
298	     *         is blank after normalisation, the telephone cannot form a valid
299	     *         E.164 number, or a supplied registration date is later than the
300	     *         server date, in which case the request must be rejected with
301	     *         {@code 400 Bad Request}
302	     */
303	    private boolean normalizeNewOwner(Owner owner) {
304	        if (!normalizeAddressFields(owner)) {
305	            return false;
306	        }
307	        String telephone = Telephones.toE164(owner.getTelephone());
308	        if (telephone == null) {
309	            return false;
310	        }
311	        owner.setTelephone(telephone);
312	        if (owner.getEmail() != null) {
313	            String email = owner.getEmail().toLowerCase();
314	            owner.setEmail(email);
315	            if (emailDomainIsBlocked(email)) {
316	                return false;
317	            }
318	        }
319	        if (!owner.postcodeValidForLocality()) {
320	            return false;
321	        }
322	        if (owner.getRegistrationDate() == null) {
323	            owner.setRegistrationDate(LocalDate.now());
324	        } else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
325	            return false;
326	        }
327	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
328	        return true;
329	    }
330	
331	    /**
332	     * Normalise the owner's address fields in place to their canonical stored form
333	     * (trimmed, whitespace-collapsed, upper-cased and with common abbreviations
334	     * expanded; see {@link Owner#normalizeAddress(String)}), gathering the whole address
335	     * concern of {@link #normalizeNewOwner} in one place. The structured form is
336	     * preferred: when a non-blank {@code addressLine1} is supplied it (and any
337	     * {@code addressLine2}) is normalised, and the flat {@code address} is composed from
338	     * them — the normalised {@code addressLine1}, with a single space and the normalised
339	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the
340	     * flat {@code address} is normalised on its own, preserving backward compatibility.
341	     * Either way the canonicalised values are written back so every later household
342	     * comparison and read sees them.
343	     *
344	     * @param owner the freshly-mapped owner whose address fields are being normalised
345	     * @return {@code true} once an address is valid and stored, or {@code false} when
346	     *         neither a structured {@code addressLine1} nor a flat {@code address} is
347	     *         present after normalisation, in which case the request must be rejected
348	     *         with {@code 400 Bad Request}
349	     */
350	    private boolean normalizeAddressFields(Owner owner) {
351	        String addressLine1 = Owner.normalizeAddress(owner.getAddressLine1());
352	        if (!addressLine1.isEmpty()) {
353	            owner.setAddressLine1(addressLine1);
354	            String composed = addressLine1;
355	            String addressLine2 = Owner.normalizeAddress(owner.getAddressLine2());
356	            if (!addressLine2.isEmpty()) {
357	                owner.setAddressLine2(addressLine2);
358	                composed = addressLine1 + " " + addressLine2;
359	            }
360	            owner.setAddress(composed);
361	            return true;
362	        }
363	        String address = Owner.normalizeAddress(owner.getAddress());
364	        if (address.isEmpty()) {
365	            return false;
366	        }
367	        owner.setAddress(address);
368	        return true;
369	    }
370	
371	    /**
372	     * Email domains that identify disposable, throw-away mailboxes. An owner whose
373	     * email address is on one of these domains is rejected with {@code 400 Bad
374	     * Request} rather than created.
375	     */
376	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
377	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
378	
379	    /**
380	     * Whether the given (already lower-cased) email address belongs to a disposable
381	     * mailbox domain on the blocklist. The domain is the part after the final
382	     * {@code '@'}; an address without one is treated as having no blocked domain.
383	     *
384	     * @param email the owner's normalised (lower-cased) email address
385	     * @return {@code true} if the email's domain is on the disposable-domain blocklist
386	     */
387	    private static boolean emailDomainIsBlocked(String email) {
388	        int at = email.lastIndexOf('@');
389	        if (at < 0) {
390	            return false;
391	        }
392	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
393	    }
394	
395	    /**
396	     * The fixed list of public holidays on which the clinic is closed. A registration
397	     * date that lands on one of these dates is treated the same as a weekend and rolled
398	     * forward past it (see {@link #rollToBusinessDay(LocalDate)}).
399	     */
400	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
401	        LocalDate.of(2026, 1, 1),
402	        LocalDate.of(2026, 1, 26),
403	        LocalDate.of(2026, 4, 25),
404	        LocalDate.of(2026, 12, 25),
405	        LocalDate.of(2026, 12, 28));
406	
407	    /**
408	     * Roll the given date forward to the next business day when it falls on a weekend or
409	     * a listed public holiday: a Saturday, Sunday or public holiday is advanced one day
410	     * at a time until a non-holiday weekday is reached, while a plain business day is
411	     * returned unchanged. Because rolling off a weekend can land on a holiday (and vice
412	     * versa), the advance repeats until the date is neither. Applied to the effective
413	     * registration date (whether supplied in the request or defaulted to the server date)
414	     * so that every value derived from it uses the adjusted business day.
415	     *
416	     * @param date the effective registration date
417	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
418	     */
419	    private static LocalDate rollToBusinessDay(LocalDate date) {
420	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
421	            date = date.plusDays(1);
422	        }
423	        return date;
424	    }
425	
426	    /**
427	     * Whether the given date falls on a weekend (Saturday or Sunday).
428	     */
429	    private static boolean isWeekend(LocalDate date) {
430	        return switch (date.getDayOfWeek()) {
431	            case SATURDAY, SUNDAY -> true;
432	            default -> false;
433	        };
434	    }
435	
436	    /**
437	     * Find the existing owners that belong to the same household as the given owner,
438	     * i.e. share the same last name (compared case-insensitively with runs of
439	     * whitespace collapsed to a single space) and postcode, and so resolve to the same
440	     * deterministic {@code householdId}. Soft-deleted owners are excluded, so the result
441	     * holds only current household members. Evaluated before the new owner is saved, so
442	     * it reflects only owners that already existed at creation time; an owner joining no
443	     * existing household yields an empty list.
444	     *
445	     * @param owner the candidate owner being created
446	     * @return the current members of the owner's household, empty if none exists
447	     */
448	    private List<Owner> findHouseholdMembers(Owner owner) {
449	        return activeOwners()
450	            .filter(existing -> existing.sameHouseholdAs(owner))
451	            .toList();
452	    }
453	
454	    /**
455	     * Whether the candidate owner is a hard duplicate of an existing owner, i.e. it shares
456	     * the {@link Owner#getIdentityKey() identity key} (the SHA-256 digest over its
457	     * normalised telephone, lower-cased email and the Soundex of its last name) of a
458	     * current owner. Soft-deleted owners are ignored, so only the current owner population
459	     * is considered. A create whose identity key collides with an existing owner is
460	     * rejected with {@code 409 Conflict}. Evaluated after normalisation (so the
461	     * email-domain blocklist has already been applied) and before the owner is saved.
462	     *
463	     * @param owner the candidate owner being created, after normalisation
464	     * @return {@code true} if an existing, non-deleted owner shares the candidate's
465	     *         identity key
466	     */
467	    private boolean isDuplicateIdentity(Owner owner) {
468	        String identityKey = owner.getIdentityKey();
469	        return activeOwners()
470	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
471	    }
472	
473	    /**
474	     * The existing owners that are still active, i.e. those not flagged as soft-deleted.
475	     * Evaluated fresh against the saved owners each call, so it reflects only owners that
476	     * already existed at creation time; a soft-deleted owner is excluded and so takes no
477	     * part in the household resolution built on top of it. Isolating the exclusion here
478	     * keeps the "current owner population" one candidate is compared against in one place.
479	     *
480	     * @return a stream of the current, non-deleted owners
481	     */
482	    private Stream<Owner> activeOwners() {
483	        return this.clinicService.findAllOwners().stream()
484	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()));
485	    }
486	
487	    /**
488	     * Assign the owner's computed-at-creation attributes in place: its customer code,
489	     * namesake count, membership number, bulk-signup warning and household size. Unlike
490	     * the {@code @Transient} attributes {@link Owner} recomputes on demand, these are
491	     * derived once here — from the owner's own (already normalised) fields and from the
492	     * wider owner population — and persisted with the owner. Run after normalisation,
493	     * household resolution and the identity-key check, so every value reflects the
494	     * owner's final field values and any household it has joined, and immediately before
495	     * the owner is saved.
496	     *
497	     * <p>Ordering matters: the customer code is assigned first because the membership
498	     * number is built from it.
499	     *
500	     * @param owner the candidate owner being created, after household resolution
501	     * @param declaredHouseholdMember whether this owner was created as a declared member
502	     *                                of an existing household (it shared an existing
503	     *                                owner's household and set {@code sharesHousehold}),
504	     *                                in which case it is not a suspected duplicate
505	     * @param householdMembers        the existing members of the owner's household at
506	     *                                creation time, used to derive its level ceiling
507	     */
508	    private void assignDerivedAttributes(Owner owner, boolean declaredHouseholdMember,
509	            List<Owner> householdMembers) {
510	        owner.setCustomerCode(deduplicatedCustomerCode(owner));
511	        owner.setNamesakeCount(countNamesakes(owner));
512	        owner.setMembershipNumber(owner.computeMembershipNumber());
513	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
514	        owner.setHouseholdSize(householdSize(owner));
515	        owner.setMembershipLevelCap(membershipLevelCap(householdMembers));
516	        assignPossibleDuplicate(owner, declaredHouseholdMember);
517	    }
518	
519	    /**
520	     * The household level ceiling to assign to the candidate owner: one above the highest
521	     * {@link Owner#getMembershipLevel() membership level} currently held by an existing
522	     * member of its household, or {@code null} when the household has no existing member
523	     * (so no ceiling applies). This bounds a new owner's reported membership level to at
524	     * most one above its household, keeping households from being outranked at the moment a
525	     * relative joins. Evaluated before the owner is saved, over the members that already
526	     * existed at creation time.
527	     *
528	     * @param householdMembers the existing members of the owner's household
529	     * @return the level ceiling to assign, or {@code null} when uncapped
530	     */
531	    private Integer membershipLevelCap(List<Owner> householdMembers) {
532	        return householdMembers.stream()
533	            .map(Owner::getMembershipLevel)
534	            .max(Comparator.naturalOrder())
535	            .map(max -> max + 1)
536	            .orElse(null);
537	    }
538	
539	    /**
540	     * Compute the customer code to assign to the candidate owner, de-duplicated against
541	     * every existing owner's customer code. The base code is the owner's computed
542	     * {@code <REGION>-<HASH8>} (see {@link Owner#computeCustomerCode()}); when it does not
543	     * already belong to an existing owner it is used unchanged. Otherwise it collides, and
544	     * {@code -<n>} is appended with the smallest integer {@code n} of 2 or more that yields
545	     * a code no existing owner holds, so the returned customer code is unique. Evaluated
546	     * before the owner is saved, so only pre-existing owners are considered.
547	     *
548	     * @param owner the candidate owner being created, after normalisation
549	     * @return the unique (de-duplicated) customer code to assign
550	     */
551	    private String deduplicatedCustomerCode(Owner owner) {
552	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
553	            .map(Owner::getCustomerCode)
554	            .filter(code -> code != null)
555	            .collect(java.util.stream.Collectors.toSet());
556	        String base = owner.computeCustomerCode();
557	        if (!existingCodes.contains(base)) {
558	            return base;
559	        }
560	        int n = 2;
561	        while (existingCodes.contains(base + "-" + n)) {
562	            n++;
563	        }
564	        return base + "-" + n;
565	    }
566	
567	    /**
568	     * Flag the candidate owner as a possible duplicate of an existing owner. A soft
569	     * match is an existing owner that shares this owner's last name (compared
570	     * case-insensitively) and postcode but carries a different (normalised) telephone.
571	     * When such a match exists the owner is still created, but with
572	     * {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to the matching
573	     * owner's id; otherwise {@code possibleDuplicate} is false and no match id is
574	     * recorded. The earliest-created matching owner (lowest id) is chosen so the result
575	     * is deterministic. Evaluated before the owner is saved, so only pre-existing owners
576	     * are considered.
577	     *
578	     * <p>A declared household member — one that shared an existing owner's household
579	     * (same last name and postcode) and was admitted because it set
580	     * {@code sharesHousehold} — is never flagged: a declared member is not a suspected
581	     * duplicate, so its {@code possibleDuplicate} is false with no match id.
582	     *
583	     * @param owner the candidate owner being created, after household resolution
584	     * @param declaredHouseholdMember whether the owner is a declared household member
585	     */
586	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
587	        if (declaredHouseholdMember) {
588	            owner.setPossibleDuplicate(false);
589	            owner.setPossibleDuplicateOf(null);
590	            return;
591	        }
592	        Optional<Owner> match = this.clinicService.findAllOwners().stream()
593	            .filter(existing -> isSoftMatch(owner, existing))
594	            .min(Comparator.comparing(Owner::getId));
595	        if (match.isPresent()) {
596	            owner.setPossibleDuplicate(true);
597	            owner.setPossibleDuplicateOf(match.get().getId());
598	        } else {
599	            owner.setPossibleDuplicate(false);
600	            owner.setPossibleDuplicateOf(null);
601	        }
602	    }
603	
604	    /**
605	     * Whether an already-created {@code existing} owner is a soft-match for the candidate
606	     * {@code owner}: their {@link Owner#getIdentityKey() identity keys} differ (so they are
607	     * not a hard duplicate) yet the {@link Owner#soundex(String) Soundex} of their last
608	     * names and their postcodes match. This is the single soft-match test
609	     * {@link #assignPossibleDuplicate} applies across the owner population, isolated here so
610	     * the comparison that decides a suspected duplicate lives in one place. Two owners
611	     * sharing a last name and postcode but with different telephones therefore soft-match
612	     * rather than being rejected, since the telephone is part of the identity key.
613	     *
614	     * @param owner    the candidate owner being created
615	     * @param existing an already-created owner to test against it
616	     * @return {@code true} if {@code existing} is a soft-match for the candidate
617	     */
618	    private boolean isSoftMatch(Owner owner, Owner existing) {
619	        String postcode = owner.getPostcode();
620	        return postcode != null && postcode.equals(existing.getPostcode())
621	            && Owner.soundex(owner.getLastName()).equals(Owner.soundex(existing.getLastName()))
622	            && !owner.getIdentityKey().equals(existing.getIdentityKey());
623	    }
624	
625	    /**
626	     * Count how many owners belong to the given owner's household once this create
627	     * completes: the owners that already share its deterministic {@code householdId}
628	     * (derived from last name and postcode) plus the owner being created. Evaluated
629	     * after the owner's {@code householdId} has been assigned. An owner whose
630	     * {@code householdId} matches no existing owner is a household of one.
631	     *
632	     * @param owner the candidate owner being created, after household resolution
633	     * @return the household member count after this create (at least {@code 1})
634	     */
635	    private int householdSize(Owner owner) {
636	        String householdId = owner.getHouseholdId();
637	        if (householdId == null) {
638	            return 1;
639	        }
640	        long existing = this.clinicService.findAllOwners().stream()
641	            .filter(other -> householdId.equals(other.getHouseholdId()))
642	            .count();
643	        return (int) existing + 1;
644	    }
645	
646	    /**
647	     * Count the existing owners that share the given owner's first and last name,
648	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
649	     * before the new owner is saved, so the result reflects only owners that
650	     * already existed at creation time.
651	     *
652	     * @param owner the candidate owner being created
653	     * @return the number of existing namesakes
654	     */
655	    private int countNamesakes(Owner owner) {
656	        String firstName = normalizeName(owner.getFirstName());
657	        String lastName = normalizeName(owner.getLastName());
658	        return (int) this.clinicService.findAllOwners().stream()
659	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
660	                && normalizeName(existing.getLastName()).equals(lastName))
661	            .count();
662	    }
663	
664	    private static String normalizeName(String value) {
665	        return value == null ? "" : value.trim().toLowerCase();
666	    }
667	
668	    /**
669	     * Determine whether the given city has already reached its owner capacity, i.e.
670	     * it already contains 50 or more existing owners (compared case-insensitively
671	     * with surrounding whitespace trimmed). A new owner may not be created in a city
672	     * that is at capacity.
673	     *
674	     * @param city the candidate owner's city
675	     * @return {@code true} if the city already holds 50 or more owners
676	     */
677	    private boolean cityIsAtCapacity(String city) {
678	        String normalizedCity = normalizeName(city);
679	        long count = this.clinicService.findAllOwners().stream()
680	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
681	            .count();
682	        return count >= 50;
683	    }
684	
685	    /**
686	     * Determine whether the daily owner-creation limit has already been reached, i.e.
687	     * 100 or more owners already carry the given registration date. A new owner may
688	     * not be created once that day's cap is reached.
689	     *
690	     * @param registrationDate the registration date the new owner would be created with
691	     * @return {@code true} if 100 or more existing owners share that registration date
692	     */
693	    private boolean dailyLimitReached(LocalDate registrationDate) {
694	        long count = this.clinicService.findAllOwners().stream()
695	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
696	            .count();
697	        return count >= 100;
698	    }
699	
700	    /**
701	     * Determine whether more than 80 owners have already been created for the given
702	     * registration date, i.e. strictly more than 80 existing owners carry that date.
703	     * Evaluated before the new owner is saved, so it reflects only owners that
704	     * already existed at creation time.
705	     *
706	     * @param registrationDate the registration date the new owner would be created with
707	     * @return {@code true} if more than 80 existing owners share that registration date
708	     */
709	    private boolean bulkSignupWarning(LocalDate registrationDate) {
710	        long count = this.clinicService.findAllOwners().stream()
711	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
712	            .count();
713	        return count > 80;
714	    }
715	
716	    /**
717	     * Write the create audit record for a freshly-saved owner. Keeps the audit format in
718	     * one place so it stays in step with the owner's identity: it reports the assigned
719	     * customer code alongside the owner's id, registration date, membership level and
720	     * membership number.
721	     *
722	     * @param owner the owner that has just been created and saved
723	     */
724	    private void auditOwnerCreated(Owner owner) {
725	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
726	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
727	            owner.getMembershipNumber());
728	    }
729	}
